function CodeLab({ toast, onUserUpdate }) {
  const [category, setCategory] = useState(
    () => localStorage.getItem("challenge_category") || "web"
  );

  const [challenges, setChallenges] = useState([]);
  const [selected, setSelected] = useState(null);
  const [code, setCode] = useState("");
  const [language, setLanguage] = useState("javascript");
  const [quizAnswer, setQuizAnswer] = useState(null);
  const [busy, setBusy] = useState(false);
  const [result, setResult] = useState(null);
  const [tab, setTab] = useState("catalog");

  const load = useCallback(async () => {
    try {
      const response = await api.get("/api/challenges", {
        params: {
          category,
        },
      });

      setChallenges(
        Array.isArray(response.data?.items)
          ? response.data.items
          : []
      );
    } catch (error) {
      setChallenges([]);
      toast(
        "error",
        "Challenge xatosi",
        errMsg(error)
      );
    }
  }, [category, toast]);

  useEffect(() => {
    load();
    setSelected(null);
    setTab("catalog");
    setResult(null);
    setQuizAnswer(null);
  }, [load]);

  async function openChallenge(challenge) {
    try {
      const response = await api.get(
        `/api/challenges/${challenge.id}`
      );

      const item =
        response.data?.challenge ||
        response.data;

      setSelected(item);

      setCode(
        item.starterCode || ""
      );

      setLanguage(
        item.type === "QUIZ"
          ? "javascript"
          : item.language || "javascript"
      );

      setQuizAnswer(null);
      setResult(null);
      setTab("editor");
    } catch (error) {
      toast(
        "error",
        "Challenge",
        errMsg(error)
      );
    }
  }

  async function submit() {
    if (!selected) return;

    if (
      selected.type === "QUIZ" &&
      quizAnswer === null
    ) {
      toast(
        "error",
        "Javob tanlang",
        "Quiz variantini tanlang."
      );
      return;
    }

    if (
      selected.type !== "QUIZ" &&
      !code.trim()
    ) {
      toast(
        "error",
        "Kod bo‘sh",
        "Kod yozing."
      );
      return;
    }

    setBusy(true);
    setResult(null);

    try {
      const payload =
        selected.type === "QUIZ"
          ? {
              answer: Number(quizAnswer),
            }
          : {
              code,
              language,
            };

      const response = await api.post(
        `/api/challenges/${selected.id}/submit`,
        payload
      );

      const data =
        response.data || {};

      setResult(data);

      try {
        const profileResponse =
          await api.get("/api/profile");

        if (
          profileResponse.data?.user
        ) {
          onUserUpdate(
            profileResponse.data.user
          );
        }
      } catch {
        // Submission muvaffaqiyatli bo‘lgan.
      }

      toast(
        "success",
        data.passed
          ? "Test o‘tdi"
          : "Kod baholandi",
        `Natija: ${data.score ?? 0}/100`
      );

      await load();
    } catch (error) {
      toast(
        "error",
        "Submit xatosi",
        errMsg(error)
      );
    } finally {
      setBusy(false);
    }
  }

  const currentCategory =
    CAT.find(
      (item) =>
        item.id === category
    );

  return (
    <div className="space-y-6">
      <Header
        eyebrow="AI Code Lab"
        title="Challenge + AI Evaluation"
        subtitle="Yo‘nalishni tanlang, test yoki kod challenge bajaring, real score va level yig‘ing."
        action={
          tab === "editor" ? (
            <Button
              variant="secondary"
              onClick={() =>
                setTab("catalog")
              }
              icon={ArrowLeft}
            >
              Challenge'lar
            </Button>
          ) : null
        }
      />

      {/* CATEGORIES */}
      <div className="grid gap-3 md:grid-cols-4">
        {CAT.map((item) => {
          const Icon = item.icon;

          return (
            <button
              key={item.id}
              type="button"
              onClick={() => {
                setCategory(item.id);

                localStorage.setItem(
                  "challenge_category",
                  item.id
                );
              }}
              className={cn(
                "rounded-2xl border p-4 text-left transition-all",
                category === item.id
                  ? "border-violet-400/30 bg-violet-500/10"
                  : "border-white/10 bg-white/[0.03] hover:bg-white/[0.05]"
              )}
            >
              <Icon
                size={18}
                className="text-violet-300"
              />

              <div className="mt-3 text-sm font-bold">
                {item.title}
              </div>

              <div className="mt-1 text-[11px] leading-5 text-slate-600">
                {item.desc}
              </div>
            </button>
          );
        })}
      </div>

      {/* CATALOG */}
      {tab === "catalog" && (
        <Glass className="p-5">
          <div className="flex items-center justify-between">
            <div>
              <div className="text-lg font-bold">
                {currentCategory?.title ||
                  "Challenge katalogi"}
              </div>

              <div className="mt-1 text-xs text-slate-600">
                Real challenge katalogi
              </div>
            </div>

            <div className="text-xs text-slate-600">
              {challenges.length} challenge
            </div>
          </div>

          {challenges.length === 0 ? (
            <div className="mt-5 rounded-2xl border border-dashed border-white/10 p-8 text-center text-sm text-slate-600">
              Bu yo‘nalishda hozircha
              challenge yo‘q.
            </div>
          ) : (
            <div className="mt-5 grid gap-4 lg:grid-cols-2">
              {challenges.map(
                (challenge) => (
                  <Glass
                    key={challenge.id}
                    onClick={() =>
                      openChallenge(
                        challenge
                      )
                    }
                    className="p-5 cursor-pointer"
                  >
                    <div className="flex items-start justify-between">
                      <div className="rounded-xl bg-white/[0.05] p-2 text-cyan-300">
                        <FileCode2 size={16} />
                      </div>

                      <div className="text-xs text-amber-300">
                        {challenge.points ??
                          0}{" "}
                        pts
                      </div>
                    </div>

                    <div className="mt-4 text-lg font-bold">
                      {challenge.title}
                    </div>

                    <div className="mt-2 text-sm leading-6 text-slate-500">
                      {challenge.description}
                    </div>

                    <div className="mt-4 flex flex-wrap items-center gap-2 text-[10px] text-slate-600">
                      <span className="rounded-full border border-white/10 px-2 py-1">
                        {challenge.type ===
                        "QUIZ"
                          ? "QUIZ"
                          : challenge.language}
                      </span>

                      <span className="rounded-full border border-white/10 px-2 py-1">
                        {challenge.difficulty ||
                          "normal"}
                      </span>

                      {challenge.completed && (
                        <span className="rounded-full border border-emerald-400/20 bg-emerald-500/5 px-2 py-1 text-emerald-300">
                          COMPLETED
                        </span>
                      )}
                    </div>

                    <div className="mt-5 text-xs font-semibold text-violet-300">
                      Ochish →
                    </div>
                  </Glass>
                )
              )}
            </div>
          )}
        </Glass>
      )}

      {/* EDITOR */}
      {tab === "editor" &&
        selected && (
          <div className="grid gap-4 xl:grid-cols-[0.75fr_1.25fr_0.9fr]">
            {/* PROBLEM */}
            <Glass className="p-5">
              <div className="text-xs font-semibold uppercase tracking-wider text-cyan-300">
                Problem
              </div>

              <div className="mt-2 text-xl font-bold">
                {selected.title}
              </div>

              <p className="mt-4 text-sm leading-7 text-slate-400">
                {selected.description}
              </p>

              {selected.type ===
              "QUIZ" ? (
                <>
                  <div className="mt-5 text-xs font-semibold text-slate-500">
                    QUESTION
                  </div>

                  <div className="mt-2 rounded-2xl bg-black/20 p-4 text-sm leading-6 text-slate-300">
                    {
                      selected.quiz
                        ?.question
                    }
                  </div>
                </>
              ) : (
                <>
                  <div className="mt-5 text-xs font-semibold text-slate-500">
                    INPUT
                  </div>

                  <pre className="mt-2 overflow-auto rounded-2xl bg-black/20 p-4 text-xs text-slate-300">
                    {selected.inputExample ||
                      "-"}
                  </pre>

                  <div className="mt-5 text-xs font-semibold text-slate-500">
                    EXPECTED OUTPUT
                  </div>

                  <pre className="mt-2 overflow-auto rounded-2xl bg-black/20 p-4 text-xs text-slate-300">
                    {selected.outputExample ||
                      "-"}
                  </pre>
                </>
              )}

              <div className="mt-5 rounded-2xl border border-violet-400/10 bg-violet-500/[0.04] p-4 text-xs leading-5 text-slate-500">
                AI correctness +
                security + speed +
                quality bo‘yicha feedback
                beradi. To‘g‘ri bajarganingizda
                score va level oshadi.
              </div>
            </Glass>

            {/* CODE / QUIZ */}
            <Glass className="overflow-hidden">
              {selected.type ===
              "QUIZ" ? (
                <div className="p-6">
                  <div className="text-sm font-semibold text-violet-300">
                    Javobni tanlang
                  </div>

                  <div className="mt-5 space-y-3">
                    {(
                      selected.quiz
                        ?.options || []
                    ).map(
                      (option, index) => (
                        <button
                          key={
                            option
                          }
                          type="button"
                          onClick={() =>
                            setQuizAnswer(
                              index
                            )
                          }
                          className={cn(
                            "w-full rounded-2xl border p-4 text-left text-sm transition",
                            quizAnswer ===
                              index
                              ? "border-violet-400/40 bg-violet-500/10"
                              : "border-white/10 bg-white/[0.02] hover:bg-white/[0.04]"
                          )}
                        >
                          {String.fromCharCode(
                            65 + index
                          )}
                          . {option}
                        </button>
                      )
                    )}
                  </div>

                  <div className="mt-6 flex justify-end">
                    <Button
                      disabled={
                        busy ||
                        quizAnswer ===
                          null
                      }
                      onClick={submit}
                      icon={
                        busy
                          ? Loader2
                          : Check
                      }
                    >
                      {busy
                        ? "Tekshirilmoqda..."
                        : "Javobni yuborish"}
                    </Button>
                  </div>
                </div>
              ) : (
                <>
                  <div className="flex items-center justify-between border-b border-white/10 px-4 py-3">
                    <div className="flex items-center gap-2 text-sm font-semibold">
                      <Code2
                        size={16}
                        className="text-violet-300"
                      />

                      solution.
                      {language ===
                      "javascript"
                        ? "js"
                        : language ===
                            "typescript"
                          ? "ts"
                          : language ===
                              "python"
                            ? "py"
                            : language ===
                                "cpp"
                              ? "cpp"
                              : "cs"}
                    </div>

                    <select
                      value={
                        language
                      }
                      onChange={(event) =>
                        setLanguage(
                          event.target
                            .value
                        )
                      }
                      className="rounded-xl border border-white/10 bg-[#11121a] px-3 py-2 text-xs text-white"
                    >
                      <option value="javascript">
                        JavaScript
                      </option>

                      <option value="typescript">
                        TypeScript
                      </option>

                      <option value="python">
                        Python
                      </option>

                      <option value="cpp">
                        C++
                      </option>

                      <option value="csharp">
                        C#
                      </option>
                    </select>
                  </div>

                  <div className="h-[620px]">
                    <Editor
                      height="100%"
                      language={
                        language ===
                        "cpp"
                          ? "cpp"
                          : language ===
                              "csharp"
                            ? "csharp"
                            : language ===
                                "python"
                              ? "python"
                              : language
                      }
                      theme="vs-dark"
                      value={
                        code
                      }
                      onChange={(
                        value
                      ) =>
                        setCode(
                          value || ""
                        )
                      }
                      options={{
                        minimap: {
                          enabled: false,
                        },
                        fontSize: 14,
                        automaticLayout: true,
                        padding: {
                          top: 16,
                        },
                        scrollBeyondLastLine: false,
                      }}
                    />
                  </div>

                  <div className="flex justify-end border-t border-white/10 p-3">
                    <Button
                      disabled={
                        busy
                      }
                      onClick={
                        submit
                      }
                      icon={
                        busy
                          ? Loader2
                          : Play
                      }
                    >
                      {busy
                        ? "Tekshirilmoqda..."
                        : "Run tests + AI"}
                    </Button>
                  </div>
                </>
              )}
            </Glass>

            {/* RESULT */}
            <div className="grid gap-4">
              <Glass className="overflow-hidden">
                <div className="border-b border-white/10 px-5 py-4">
                  <div className="flex items-center gap-2 text-sm font-bold">
                    <Terminal
                      size={16}
                      className="text-emerald-300"
                    />
                    Terminal
                  </div>
                </div>

                <div className="h-[310px] overflow-auto bg-black/30 p-5 font-mono text-xs leading-6 text-slate-500">
                  {result ? (
                    <>
                      {(
                        result.test
                          ?.results ||
                        []
                      ).map(
                        (test) => (
                          <div
                            key={
                              test.index
                            }
                            className={
                              test.passed
                                ? "text-emerald-300"
                                : "text-red-300"
                            }
                          >
                            Test{" "}
                            {
                              test.index
                            }
                            :{" "}
                            {test.passed
                              ? "PASS"
                              : "FAIL"}{" "}
                            | expected=
                            {
                              test.expected
                            }{" "}
                            | actual=
                            {
                              test.actual
                            }
                          </div>
                        )
                      )}

                      <pre className="mt-3 whitespace-pre-wrap">
                        {result.test
                          ?.output ||
                          result.feedback ||
                          ""}
                      </pre>
                    </>
                  ) : (
                    <div className="space-y-2">
                      <div>
                        › $ devrank challenge
                      </div>

                      <div>
                        › Waiting for submit...
                      </div>
                    </div>
                  )}
                </div>
              </Glass>

              <Glass className="p-5">
                <div className="flex items-center gap-2 text-sm font-bold">
                  <Sparkles
                    size={16}
                    className="text-violet-300"
                  />

                  AI Evaluation
                </div>

                {result ? (
                  <div className="mt-5 space-y-4">
                    <div className="rounded-2xl bg-gradient-to-br from-violet-500/10 to-cyan-500/5 p-4">
                      <div className="text-xs text-slate-500">
                        Overall
                      </div>

                      <div className="mt-1 text-4xl font-black">
                        {result.score ??
                          result.overall ??
                          0}
                        /100
                      </div>
                    </div>

                    <Progress
                      label="Correctness"
                      value={
                        result.correctness ||
                        0
                      }
                      tone="emerald"
                    />

                    <Progress
                      label="Quality"
                      value={
                        result.quality ||
                        0
                      }
                      tone="violet"
                    />

                    <Progress
                      label="Security"
                      value={
                        result.security ||
                        0
                      }
                      tone="amber"
                    />

                    <Progress
                      label="Speed"
                      value={
                        result.speed ||
                        0
                      }
                      tone="cyan"
                    />

                    <div className="rounded-2xl border border-white/8 bg-white/[0.02] p-4 text-xs leading-6 text-slate-500">
                      {result.feedback ||
                        "Feedback mavjud emas."}
                    </div>

                    <div className="text-[10px] text-slate-700">
                      Model:{" "}
                      {result.model ||
                        "unknown"}
                    </div>

                    {result.passed && (
                      <div className="rounded-2xl border border-emerald-400/15 bg-emerald-500/5 p-4 text-sm font-semibold text-emerald-300">
                        ✓ Challenge
                        muvaffaqiyatli
                        bajarildi.
                        <br />
                        Score va
                        level backend
                        tomonidan
                        yangilandi.
                      </div>
                    )}
                  </div>
                ) : (
                  <div className="py-14 text-center text-sm text-slate-600">
                    Yuboring — test natijasi
                    va Gemini feedback shu
                    yerda chiqadi.
                  </div>
                )}
              </Glass>
            </div>
          </div>
        )}
    </div>
  );
}
